scwin.trigger1_onclick = function(e) {
    //rowvisible 함수처리시 0 줄만 안 사라지고 2줄이 없어짐 
    //grd_test.getRowVisible(0);
    grd_test.setRowVisible(0, false);
    //grd_test.setRowVisible(3, false);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'grd_test_headerRowNumber_bodyRow_12').parentElement).hasClass('w2grid_hidedRow') == false;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
